/** Lightweight language hints for speech routing, with the device locale for ambiguous replies.
 * This does not constrain the language generated by the assistant. */
export function speechLanguage(text: string): string {
  const words = new Set(text.toLowerCase().match(/[\p{L}]+/gu) ?? []);
  const hints: Record<string, string[]> = {
    'it-IT': ['ciao', 'sono', 'saldo', 'tuo', 'pagamento', 'ricevuto', 'puoi', 'grazie', 'conferma', 'inviare'],
    'en-US': ['hello', 'your', 'the', 'balance', 'payment', 'received', 'please', 'thank', 'confirm', 'send'],
    'fr-FR': ['bonjour', 'votre', 'solde', 'paiement', 'reçu', 'merci', 'confirmer', 'envoyer'],
    'de-DE': ['hallo', 'dein', 'guthaben', 'zahlung', 'erhalten', 'danke', 'bestätigen', 'senden'],
    'es-ES': ['hola', 'saldo', 'pago', 'recibido', 'gracias', 'puedes', 'confirmar', 'enviar'],
  };
  const ranked = Object.entries(hints).map(([language, markers]) => ({ language, score: markers.filter(word => words.has(word)).length })).sort((a, b) => b.score - a.score);
  if (ranked[0].score > 0 && ranked[0].score > ranked[1].score) return ranked[0].language;
  return Intl.DateTimeFormat().resolvedOptions().locale || 'en-US';
}

// QVAC 0.21's Supertonic schema rejects the native engine's language-agnostic `na`.
const SUPERTONIC_LANGUAGES = new Set('en ko ja ar bg cs da de el es et fi fr hi hr hu id it lt lv nl pl pt ro ru sk sl sv tr uk vi'.split(' '));
export function supertonicLanguage(text: string): string {
  const language = speechLanguage(text).split(/[-_]/)[0].toLowerCase();
  return SUPERTONIC_LANGUAGES.has(language) ? language : 'en';
}
